#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }
    long num = strtol(argv[1], NULL, 10);
    long den = strtol(argv[2], NULL, 10);
    long a = num / den;
    long f = num % den;
    if (f == 0) {
        printf("%ld", a);
    } else {
        printf("%ld;", a);
        while (f != 0) {
            long temp = den;
            den = f;
            f = temp % f;
            if (f == 0) {
                printf(" %ld", den);
            } else {
                printf(" %ld,", den);
            }
        }
    }
    puts("");
    return 0;
}
